                            "publishTime":  "2026-01-03T04:24:30.946166379Z",
                            "flagContentUri":  "https://www.google.com/local/content/rap/report?postId=Ci9DQUlRQUNvZENodHljRjlvT2xCeFpVMWFVWGxGZURodVlsRlVlbk5PTFdOcWJYYxAB\u0026d=17924085\u0026t=1",
                            "googleMapsUri":  "https://www.google.com/maps/reviews/data=!4m6!14m5!1m4!2m3!1sCi9DQUlRQUNvZENodHljRjlvT2xCeFpVMWFVWGxGZURodVlsRlVlbk5PTFdOcWJYYxAB!2m1!1s0x3442ab8e4d3491ed:0x6f50988399351d89"
