        "price_level":  null,
        "cuisine":  "蔬食料理",
        "latitude":  25.132626,
        "longitude":  121.497297,
        "url":  "https://www.google.com/maps/search/?api=1\u0026query=%E9%98%BF%E9%A6%AC%E9%9D%9E%E9%A4%90%E5%BB%B3\u0026query_place_id=ChIJfVg9VFGuQjQR3OXOjpHCw5s",
        "google_maps_url":  "https://www.google.com/maps/search/?api=1\u0026query=%E9%98%BF%E9%A6%AC%E9%9D%9E%E9%A4%90%E5%BB%B3\u0026query_place_id=ChIJfVg9VFGuQjQR3OXOjpHCw5s",
