                            "publishTime":  "2025-11-10T06:15:51.077522277Z",
                            "flagContentUri":  "https://www.google.com/local/content/rap/report?postId=Ci9DQUlRQUNvZENodHljRjlvT2w5SE9IcDVWWFk0VUVWTFpYQkROblpaU1U1emEzYxAB\u0026d=17924085\u0026t=1",
                            "googleMapsUri":  "https://www.google.com/maps/reviews/data=!4m6!14m5!1m4!2m3!1sCi9DQUlRQUNvZENodHljRjlvT2w5SE9IcDVWWFk0VUVWTFpYQkROblpaU1U1emEzYxAB!2m1!1s0x3442a9b836c59b19:0x4c594f6a650171a9"
