                            "publishTime":  "2025-09-29T04:53:44.559733459Z",
                            "flagContentUri":  "https://www.google.com/local/content/rap/report?postId=Ci9DQUlRQUNvZENodHljRjlvT201SmMwVkNOMUZ1ZGpSd1RYZGhTMkV6VmxseGVYYxAB\u0026d=17924085\u0026t=1",
                            "googleMapsUri":  "https://www.google.com/maps/reviews/data=!4m6!14m5!1m4!2m3!1sCi9DQUlRQUNvZENodHljRjlvT201SmMwVkNOMUZ1ZGpSd1RYZGhTMkV6VmxseGVYYxAB!2m1!1s0x3442abef1ee9ab4b:0x78b5356ac510f8c8"
