                            "publishTime":  "2025-12-03T06:36:11.428042384Z",
                            "flagContentUri":  "https://www.google.com/local/content/rap/report?postId=Ci9DQUlRQUNvZENodHljRjlvT2kxMFkweGxTbUpvT1dnNVNsOTJjR0YxYW14VlQwRRAB\u0026d=17924085\u0026t=1",
                            "googleMapsUri":  "https://www.google.com/maps/reviews/data=!4m6!14m5!1m4!2m3!1sCi9DQUlRQUNvZENodHljRjlvT2kxMFkweGxTbUpvT1dnNVNsOTJjR0YxYW14VlQwRRAB!2m1!1s0x3442a96c9ee61c53:0x78b9ec2c08d79fa1"
